  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #0f1117;
  --surface: #1a1d27;
  --surface-hover: #22263a;
  --border: #2e3347;
  --text-primary: #e8eaf0;
  --text-secondary: #8b90a7;
  --accent: #6c63ff;
  --accent-hover: #7c74ff;
  --danger: #e85d5d;
  --danger-hover: #f06b6b;
  --danger-bg: rgba(232, 93, 93, 0.1);
  --radius: 12px;
  --radius-sm: 8px;
  --transition: 0.2s ease;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ── Header ── */
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 40px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}

.logo {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.logo span {
  color: var(--accent);
}

nav {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-link {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 0.875rem;
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}

.nav-link:hover {
  color: var(--text-primary);
  background: var(--surface-hover);
}

.nav-link.active {
  color: var(--text-primary);
  background: var(--surface-hover);
}

/* ── Main layout ── */
main {
  flex: 1;
  max-width: 1100px;
  width: 100%;
  margin: 0 auto;
  padding: 48px 40px;
}

.page-header {
  margin-bottom: 40px;
}

.page-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: 6px;
}

.page-header p {
  color: var(--text-secondary);
  font-size: 0.9rem;
}

/* ── Image grid ── */
.image-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

.image-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition), transform var(--transition);
}

.image-card:hover {
  border-color: #3e4460;
  transform: translateY(-2px);
}

.image-card.featured {
  border-color: var(--accent);
}

.image-thumb {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  display: block;
  background: var(--surface-hover);
}

/* Placeholder gradient thumbnails */
.image-thumb.placeholder {
  background: var(--surface-hover);
  display: flex;
  align-items: center;
  justify-content: center;
}

.placeholder-1 { background: linear-gradient(135deg, #1e2a4a 0%, #2d1b69 100%); }
.placeholder-2 { background: linear-gradient(135deg, #1a3a2a 0%, #0f4c35 100%); }
.placeholder-3 { background: linear-gradient(135deg, #3a1a1a 0%, #6b2020 100%); }
.placeholder-4 { background: linear-gradient(135deg, #2a2a1a 0%, #5c5010 100%); }
.placeholder-5 { background: linear-gradient(135deg, #1a2a3a 0%, #104060 100%); }
.placeholder-6 { background: linear-gradient(135deg, #2a1a3a 0%, #501060 100%); }

.placeholder-icon {
  font-size: 2.5rem;
  opacity: 0.3;
}

.card-info {
  padding: 14px 16px;
}

.card-name {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.card-meta {
  font-size: 0.75rem;
  color: var(--text-secondary);
  margin-bottom: 14px;
}

.card-actions {
  display: flex;
  gap: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  border: none;
  text-decoration: none;
  transition: background var(--transition), color var(--transition), opacity var(--transition);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
}

.btn-ghost:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
  border-color: #3e4460;
}

.btn-danger-soft {
  background: var(--danger-bg);
  color: var(--danger);
  border: 1px solid transparent;
  flex: 1;
  justify-content: center;
}

.btn-danger-soft:hover {
  background: rgba(232, 93, 93, 0.18);
  border-color: rgba(232, 93, 93, 0.3);
}

/* ── Modal overlay ── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.65);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 20px;

  /* Hidden by default */
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.25s ease, visibility 0.25s ease;
}

.modal-overlay.is-open {
  opacity: 1;
  visibility: visible;
}

/* ── Modal dialog ── */
.modal {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  width: 100%;
  max-width: 440px;
  padding: 32px;
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.5);

  transform: scale(0.94) translateY(8px);
  transition: transform 0.25s ease;
}

.modal-overlay.is-open .modal {
  transform: scale(1) translateY(0);
}

.modal-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--danger-bg);
  border: 1px solid rgba(232, 93, 93, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.modal-icon svg {
  width: 24px;
  height: 24px;
  color: var(--danger);
}

.modal-title {
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 10px;
}

.modal-body {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 8px;
}

.modal-filename {
  display: inline-block;
  background: var(--surface-hover);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 2px 10px;
  font-size: 0.8rem;
  font-family: 'SF Mono', 'Fira Code', monospace;
  color: var(--text-primary);
  margin-top: 10px;
  margin-bottom: 24px;
  word-break: break-all;
}

.modal-warning {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(232, 93, 93, 0.08);
  border: 1px solid rgba(232, 93, 93, 0.18);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  font-size: 0.8rem;
  color: var(--danger);
  margin-bottom: 28px;
}

.modal-warning svg {
  flex-shrink: 0;
  width: 16px;
  height: 16px;
}

.modal-actions {
  display: flex;
  gap: 10px;
}

.btn-cancel {
  flex: 1;
  justify-content: center;
  background: var(--surface-hover);
  color: var(--text-primary);
  border: 1px solid var(--border);
}

.btn-cancel:hover {
  border-color: #3e4460;
  background: #2a2f45;
}

.btn-confirm-delete {
  flex: 1;
  justify-content: center;
  background: var(--danger);
  color: #fff;
  border: 1px solid transparent;
}

.btn-confirm-delete:hover {
  background: var(--danger-hover);
}

/* ── Focus visible ── */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
