+const overlay = document.getElementById('deleteModal');
+const filenamePlaceholder = document.getElementById('modalFilename');
+let pendingCard = null;
+
+function openModal(filename, card) {
+  filenamePlaceholder.textContent = filename;
+  pendingCard = card;
+  overlay.classList.add('is-open');
+  overlay.querySelector('.btn-cancel').focus();
+}
+
+function closeModal() {
+  overlay.classList.remove('is-open');
+  pendingCard = null;
+}
+
+// Open on each delete trigger
+document.querySelectorAll('.trigger').forEach(btn => {
+  btn.addEventListener('click', () => {
+    const card = btn.closest('.image-card');
+    const name = card.querySelector('.card-name').textContent;
+    openModal(name, card);
+  });
+});
+
+// Cancel button
+document.getElementById('cancelDelete').addEventListener('click', closeModal);
+
+// Confirm delete
+document.getElementById('confirmDelete').addEventListener('click', () => {
+  if (pendingCard) {
+    pendingCard.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
+    pendingCard.style.opacity = '0';
+    pendingCard.style.transform = 'scale(0.92)';
+    setTimeout(() => pendingCard.remove(), 300);
+  }
+  closeModal();
+});
+
+// Close on overlay backdrop click
+overlay.addEventListener('click', e => {
+  if (e.target === overlay) closeModal();
+});
+
+// Close on Escape
+document.addEventListener('keydown', e => {
+  if (e.key === 'Escape' && overlay.classList.contains('is-open')) closeModal();
+});
+
